#!/usr/bin/env python3
"""Remove executable JavaScript from an HTML file while preserving formatting."""
import html
import os
import re
import sys
import tempfile
import urllib.parse

SCRIPT_OPEN_RE = re.compile(r"<\s*script(?:\s|/?>)", re.I)
SCRIPT_CLOSE_RE = re.compile(r"<\s*/\s*script\s*>", re.I)
TAG_NAME_RE = re.compile(r"<\s*([A-Za-z][A-Za-z0-9:_-]*)")
ATTR_RE = re.compile(
    r"(?P<lead>\s+)(?P<name>[A-Za-z_:][A-Za-z0-9:._-]*)"
    r"(?:\s*=\s*(?P<value>\"[^\"]*\"|'[^']*'|[^\s>]*))?",
    re.S,
)

# Attributes whose values can directly execute or load script.
URL_ATTRS = {
    "href", "src", "action", " formaction", "cite", "background",
    "codebase", "data", "lowsrc", "dynsrc", "poster", "ping",
    "xlink:href",
}


def decoded_value(value):
    if value is None:
        return ""
    if len(value) >= 2 and value[0] in "\"'" and value[-1] == value[0]:
        value = value[1:-1]
    # Decode repeatedly because entities and percent escapes can be layered.
    for _ in range(3):
        new = html.unescape(urllib.parse.unquote(value))
        if new == value:
            break
        value = new
    return value.replace("\x00", "").strip().lower()


def dangerous_value(name, value):
    v = decoded_value(value)
    compact = re.sub(r"[\x00-\x20\u007f]+", "", v)
    if name in URL_ATTRS or name == "srcdoc":
        return compact.startswith("javascript:") or compact.startswith("vbscript:") or compact.startswith("data:text/html") or name == "srcdoc"
    if name == "style":
        return bool(re.search(r"(?:expression\s*\(|url\s*\(\s*['\"]?\s*(?:javascript|vbscript):|behavior\s*:|-moz-binding\s*:)", v, re.I))
    if name == "content":
        return bool(re.search(r"(?:^|;)\s*url\s*\(\s*['\"]?\s*(?:javascript|vbscript):", v, re.I))
    return False


def sanitize_tag(tag):
    """Return a tag with only dangerous attributes removed."""
    m = TAG_NAME_RE.match(tag)
    if not m:
        return tag
    tag_name = m.group(1).lower()
    if tag_name in {"script"}:
        return ""

    def replace_attr(match):
        name = match.group("name")
        low = name.lower()
        value = match.group("value")
        # HTML event handler attributes (onclick, onload, onerror, ...).
        if low.startswith("on") and len(low) > 2:
            return ""
        if low in URL_ATTRS or low in {"srcdoc", "style", "content"}:
            if dangerous_value(low, value):
                return ""
        return match.group(0)

    # Do not parse the tag's closing /> as an attribute; ATTR_RE only starts
    # after whitespace and requires an attribute-name character.
    return ATTR_RE.sub(replace_attr, tag)


def sanitize(text):
    out = []
    pos = 0
    n = len(text)
    while pos < n:
        start = text.find("<", pos)
        if start < 0:
            out.append(text[pos:])
            break
        out.append(text[pos:start])

        # Remove script element and all of its contents, including malformed
        # content up to EOF if no closing tag exists.
        if SCRIPT_OPEN_RE.match(text, start):
            close = SCRIPT_CLOSE_RE.search(text, start)
            pos = n if close is None else close.end()
            continue

        # Find the end of a tag without being confused by > inside quotes.
        i = start + 1
        quote = None
        while i < n:
            c = text[i]
            if quote:
                if c == quote:
                    quote = None
            elif c in "\"'":
                quote = c
            elif c == ">":
                i += 1
                break
            i += 1
        if i > n:
            i = n
        tag = text[start:i]
        out.append(sanitize_tag(tag))
        pos = i
    return "".join(out)


def main():
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} HTML_FILE", file=sys.stderr)
        return 2
    path = sys.argv[1]
    with open(path, "rb") as f:
        raw = f.read()
    # UTF-8 is standard for HTML; surrogateescape preserves undecodable bytes.
    text = raw.decode("utf-8", "surrogateescape")
    filtered = sanitize(text)
    encoded = filtered.encode("utf-8", "surrogateescape")
    directory = os.path.dirname(os.path.abspath(path)) or "."
    fd, temporary = tempfile.mkstemp(prefix=".filter-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(encoded)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temporary, path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
